def architecture(project,language='pt'):
    key=ALIASES.get(project['id'],project['id'])
    return ARCHITECTURE[key][1 if language=='en' else 0]

def clean(value, language='pt'):
    # Keep architectural concepts; do not expose local file locations to readers.
    value=re.sub(r'\b(?:src|frontend|backend|supabase|data|public|web|META-INF|servers|scripts|modulo|com)/[\w./\[\]-]+(?::\d+)?', 'componentes da aplicação' if language=='pt' else 'application components', str(value))
    return value

def context(project, language='pt'):
    key=ALIASES.get(project['id'],project['id'])
    values=DOMAINS.get(key)
    if values:
        offset=3 if language=='en' else 0
        return values[offset:offset+3]
    breadth=project.get('breadth',{})
    return ('; '.join(breadth.get('applicationAreas',[project['area']])),breadth.get('intendedAudience',''),breadth.get('problemAndObjective',project['summary']))

def markup(project, language='pt'):
    area,audience,objective=context(project,language)
    labels=('Área de aplicação','Público e contexto','Objetivo') if language=='pt' else ('Application area','Users and context','Objective')
    return ''.join('<p><strong>'+label+':</strong> '+html.escape(clean(value,language))+'.</p>' for label,value in zip(labels,(area,audience,objective)) if value)

def case_markup(case,projects,language='pt'):
    matched=[]
    keys=['Agrodan'] if case['id']=='case-infra-1' else [p['id'] for p in projects if any(s.startswith(p['id']+'/') or s.startswith(p['id']+'@') for s in case.get('sources',[]))]
    for key in dict.fromkeys(keys):
        p=next((p for p in projects if p['id']==key),None)
        if p:matched.append(p)
    return ''.join(markup(p,language) for p in matched)

def reader_content(markup, language='pt'):
    """Clean text nodes only; keep navigation, public URLs and HTML untouched."""
    markup=re.sub(r'<p class="scope">.*?</p>','',markup,flags=re.S)
    return re.sub(r'(?<=>)[^<>]+(?=<)',lambda m:clean(m[0],language),markup)
